import React from "react";
import { useLocation, useNavigate } from "react-router-dom"; // Import useNavigate as well
import './Result.css'; // <--- Import your CSS file here

const Result = () => {
    const location = useLocation();
    const navigate = useNavigate(); // Get the navigate function to go back
    const { style, occasion, outfit } = location.state || {};

    // Function to handle going back to the quiz
    const handleGoBack = () => {
        navigate("/"); // Navigate back to the quiz page (assuming it's at the root path "/")
    };

    if (!style || !occasion || !outfit) {
        return (
            <div className="result-container"> {/* Use container style for error message too */}
                <p className="missing-data-message">
                    Missing result data. Please go back and complete the quiz.
                </p>
                <button onClick={handleGoBack} className="back-button">
                    Go Back to Quiz
                </button>
            </div>
        );
    }

    return (
        <div className="result-container">
            <h2 className="result-title">👗 Your Style DNA Result</h2> {/* Updated title */}

            <p className="result-text"><strong>✨ Your Style:</strong> {style}</p>
            <p className="result-text"><strong>🎯 Occasion:</strong> {occasion}</p>

            <div className="outfit-suggestion-box">
                <h3>🪞 Outfit Suggestion:</h3>
                <p className="result-text">
                    Your <strong>{style}</strong> style outfit for <strong>{occasion}</strong>: {outfit}
                </p>
            </div>

            <button onClick={handleGoBack} className="back-button">
                Go Back to Quiz
            </button>
        </div>
    );
};

export default Result;
